392	            // as on screen: n/a when the grade in force today has no rate today and no claim that
393	            // counts has a figure
394	            boolean none = inForce(sheetRates, person.gradeOn(today), today).isEmpty() && !anyFigure;
395	            figures.put(person.getId(), new Figures(person.getName(), claimed, none ? null : sheet.capped(due),
396	                    overdue));
397	        }
398	        return new Snapshot(figures);
399	    }
400	
401	    /**
402	     * Each person's due of their claims that count whose date falls in from..to (both inclusive),
403	     * by person id, for every person on the sheet (0.00 when none).
404	     */
405	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
406	        Sheet sheet = sheet(sheetId);
407	        BigDecimal floor = sheet.getFloor();
408	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
409	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
410	        Map<Long, BigDecimal> dues = new LinkedHashMap<>();
411	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
412	            BigDecimal due = zero();
413	            for (Claim claim : sheetClaims) {
414	                if (!claim.getPersonId().equals(person.getId()) || !person.counts(claim)
415	                        || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
416	                    continue;
417	                }
418	                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, floor, person, claim);
419	                if (figure != null) {
420	                    due = due.add(figure);
421	                }
422	            }
423	            dues.put(person.getId(), due);
424	        }
425	        return dues;
426	    }
427	
428	    /** Record, once the change commits, the figures that moved since the snapshot taken before it. */
429	    public void recordChanges(String sheetId, String user, Snapshot before) {
430	        Snapshot after = snapshot(sheetId);
431	        String prefix = " sheet=" + sheetId + " by=" + user;
432	        boolean moved = false;
433	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
434	            Figures now = entry.getValue();
435	            Figures was = before.people().get(entry.getKey());
436	            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
437	                    && same(was.overdueTotal(), now.overdueTotal())) {
438	                continue;
439	            }
440	            moved = true;
441	            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + money(now.claimed())
442	                    + " due-total=" + money(now.dueTotal()) + " overdue-total=" + money(now.overdueTotal()));
443	        }
444	        if (moved && !(same(before.claimedTotal(), after.claimedTotal())
445	                && same(before.dueTotal(), after.dueTotal()) && same(before.overdueTotal(), after.overdueTotal()))) {
446	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + money(after.claimedTotal()) + " due-total="
447	                    + money(after.dueTotal()) + " overdue-total=" + money(after.overdueTotal()));
448	        }
449	    }
450	
451	    /**
452	     * A claim's figure as the screen shows it: the due fixed when settled, else the one bound by the
453	     * last statement (not while PENDING), else its live due (rounded as the claim rounds, see {@link Rounding}) raised to the floor (a correction's is not), with its late charge added on top;
454	     * null when none.
455	     */
456	    private static BigDecimal figure(Sheet sheet, List<Rate> sheetRates, List<Claim> sheetClaims, BigDecimal floor,
457	            Person person, Claim claim) {
458	        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
459	            return claim.getSettledDue();
460	        }
461	        BigDecimal figure = claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
462	                : inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
463	                        .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2,
464	                                Rounding.mode(sheet, Rounding.dateOf(claim, sheetClaims))))
465	                        .map(due -> claim.isCorrection() ? due : due.max(floor))
466	                        .orElse(null);
467	        return LateCharge.withCharge(sheet, claim, figure);
468	    }
469	
470	    /** Whether a claim is overdue on the sheet's today: OPEN or PENDING, and past its due-by. */
471	    private static boolean overdue(Claim claim, LocalDate today) {
472	        return claim.getStatus().isOpen() && today != null && claim.getDueBy() != null
473	                && claim.getDueBy().isBefore(today);
474	    }
475	
476	    private Sheet sheet(String sheetId) {
477	        return sheets.findById(sheetId).orElseGet(() -> new Sheet(sheetId, null, null, LocalDate.now()));
478	    }
479	
480	    /** The grade's rate in force on a date, as {@link RateRepository#findInForce} picks it. */
481	    private static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
482	        return sheetRates.stream().filter(r -> r.getGrade().equals(grade))
483	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
484	                .max((a, b) -> a.getFromDate() == null ? -1 : b.getFromDate() == null ? 1
485	                        : a.getFromDate().compareTo(b.getFromDate()))
486	                .filter(r -> r.runsThrough(date));
487	    }
488	
489	    private static boolean same(BigDecimal a, BigDecimal b) {
490	        return a == null ? b == null : b != null && a.compareTo(b) == 0;
491	    }
492	
493	    private static BigDecimal zero() {
494	        return BigDecimal.ZERO.setScale(2);
495	    }
496	
497	    private static String money(BigDecimal value) {
498	        return value == null ? "n/a" : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
499	    }
500	}
501	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
502	        if (claim.getStatus() == ClaimStatus.SETTLED) {
503	            return claim.getSettledDue();
504	        }
505	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
506	                : due(sheetId, person, claim);
507	    }
508	
509	    /** A claim's figure with its late charge on the sheet's today added on top; null when it has none. */
510	    public BigDecimal charged(String sheetId, Person person, Claim claim) {
511	        return LateCharge.withCharge(sheets.sheet(sheetId), claim, figure(sheetId, person, claim));
512	    }
513	
514	    @Transactional(readOnly = true)
515	    public List<Claim> list(String sheetId) {
516	        return claims.findBySheetIdOrderByListedDesc(sheetId);
517	    }
518	
519	    @Transactional
520	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
521	            String corrects) {
522	        Person person = person(sheetId, personId);
523	        LocalDate dated = dateOrToday(sheetId, date);
524	        periods.refuseIfClosed(sheetId, dated);
525	        refuseIfRetired(person, dated);
526	        String corrected = corrected(sheetId, personId, amount, corrects);
527	        RollupService.Snapshot before = rollup.snapshot(sheetId);
528	        Claim claim = new Claim(sheetId, personId, amount, dated,
529	                dated.plusDays(sheets.sheet(sheetId).termsFor(person.gradeOn(dated))), note, corrected);
530	        logStatus(sheetId, user, person, claim);
531	        Claim added = claims.saveAndFlush(claim);
532	        audit.recordOnCommit(record("CLAIM_ADDED", sheetId, user, person, added));
533	        rollup.recordChanges(sheetId, user, before);
534	        return added;
535	    }
536	
537	    @Transactional
538	    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note,
539	            String corrects) {
540	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
541	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
542	        if (claim.getStatus() != ClaimStatus.DRAFT) {
543	            throw new ResponseStatusException(HttpStatus.CONFLICT,
544	                    "A " + claim.getStatus() + " claim cannot be edited.");
545	        }
546	        LocalDate dated = dateOrToday(sheetId, date);
547	        periods.refuseIfClosed(sheetId, claim.getDate());
548	        periods.refuseIfClosed(sheetId, dated);
549	        refuseIfRetired(person(sheetId, claim.getPersonId()), dated);
550	        String corrected = corrected(sheetId, claim.getPersonId(), amount, corrects);
551	        RollupService.Snapshot before = rollup.snapshot(sheetId);
552	            try {
553	                settled.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
554	            } catch (ResponseStatusException refusedOne) {
555	                // every refusal is checked before the claim is changed, so it is left as it is
556	                refused++;
557	            }
558	        }
559	        return new BulkSettled(settled.size(), refused, settled);
560	    }
561	
562	    /** The given claims on the sheet in list order: people as added, newest claim first within a person. */
563	    private List<Claim> inListOrder(String sheetId, Collection<Long> ids) {
564	        Map<Long, Integer> personOrder = new HashMap<>();
565	        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
566	        for (int i = 0; i < listed.size(); i++) {
567	            personOrder.put(listed.get(i).getId(), i);
568	        }
569	        return ids.stream().distinct()
570	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
571	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
572	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
573	                .toList();
574	    }
575	
576	    /**
577	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
578	     * rounded to the cent as the claim rounds (see {@link Rounding}) and raised to the sheet's floor (a correction's is not); null with no
579	     * rate in force then.
580	     */
581	    public BigDecimal due(String sheetId, Person person, Claim claim) {
582	        Sheet sheet = sheets.sheet(sheetId);
583	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
584	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
585	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
586	                .map(due -> claim.isCorrection() ? due : due.max(sheet.getFloor()))
587	                .orElse(null);
588	    }
589	
590	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
591	    private LocalDate roundingDate(String sheetId, Claim claim) {
592	        if (!claim.isCorrection() || claim.getCorrects() == null) {
593	            return claim.getDate();
594	        }
595	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
596	    }
597	
598	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
599	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
600	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
601	                dueText(charged(sheetId, person, claim))));
602	    }
603	
604	    private static String dueText(BigDecimal due) {
605	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
606	    }
607	
608	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
609	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
610	        BigDecimal limit = sheets.clerkLimit(sheetId);
611	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
612	    }
613	
614	    private boolean isSteward(String sheetId, String user) {
615	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
616	    }
617	
618	    /**
619	     * The number a claim corrects: none unless its amount is negative, when it must name the number
620	     * of a SETTLED claim of the same person, else it is refused (400).
621	     */
622	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
623	        if (amount.signum() >= 0) {
624	            return null;
625	        }
626	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
627	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
628	        if (!settled) {
629	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
630	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
631	        }
632	        return corrects;
633	    }
634	
635	    /** Refuse (422) a claim dated after its person's retirement date. */
636	    private static void refuseIfRetired(Person person, LocalDate date) {
637	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
638	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
639	                    "That claim's date is after its person's retirement date.");
640	        }
641	    }
642	
643	    private Person person(String sheetId, long personId) {
644	        return people.findByIdAndSheetId(personId, sheetId)
645	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
646	    }
647	
648	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
649	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
650	                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
651	    }
652	
653	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
654	        return date != null ? date : sheets.today(sheetId);
655	    }
656	}
