  /** A claim's amount in whole cents when it counts toward the totals, else nothing. */
  private countedCents(p: Person | undefined, c: Claim): number {
    return countsFor(p, c) ? cents(c.amount) : 0;
  }

  /** What the person owes, in whole cents: the sum of their figures held to the sheet's cap. */
  protected dueOf(p: Person): number | null {
    const sum = this.figuresOf(p);
    const cap = this.capCents();
    return sum === null || cap === null ? sum : Math.min(sum, cap);
  }

  /** How far the sum of the person's figures is above the cap, in whole cents; 0 otherwise. */
  protected excessOf(p: Person): number {
    const sum = this.figuresOf(p);
    const cap = this.capCents();
    return sum === null || cap === null ? 0 : Math.max(sum - cap, 0);
  }

  /**
   * The sum of the figures of the person's claims that count, in whole cents. Null when their
   * grade in force on the sheet's today has no rate in force then, unless a claim that counts has
   * a figure.
   */
  private figuresOf(p: Person): number | null {
    const figures = this.claimsOf(p.id)
      .filter((c) => countsFor(p, c))
      .map((c) => chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floorCents(), this.lateness(), this.roundOn(c)));
    if (this.pctOf().get(this.gradeToday(p)) === undefined && figures.every((f) => f === null)) return null;
    return figures.reduce<number>((sum, f) => sum + (f ?? 0), 0);
  }

  /** The person's overdue claims that count: how many, and the sum of their figures in whole cents. */
  protected overdueOf(p: Person): { count: number; cents: number } {
    const today = this.session.today();
    const late = this.claimsOf(p.id).filter((c) => countsFor(p, c) && overdue(c, today));
    return {
      count: late.length,
      cents: late.reduce((sum, c) => sum + (chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floorCents(), this.lateness(), this.roundOn(c)) ?? 0), 0),
    };
  }

  protected statementOf(personId: number): StatementSummary | undefined {
    return this.statements().get(personId);
  }

  readonly personName = input.required<string>();
  readonly claims = input.required<Claim[]>();
  /** The person's grades: the one in force on a claim's date, at its rate then, gives what the claim has due. */
  readonly grades = input.required<DatedGrade[]>();
  /** The sheet's rates. */
  readonly rates = input.required<Rate[]>();
  /** The sheet's floor in whole cents: the least a claim's live due can be. */
  readonly floor = input.required<number>();
  /** The sheet's late percent: what an overdue claim gains of its figure for every full 30 days. */
  readonly latePct = input.required<string>();
  /** The sheet's policy date (blank: its today): a claim dated before it rounds half up, else half to even. */
  readonly policyDate = input.required<string>();
  /** The sheet's periods. */
  readonly periods = input.required<Period[]>();
  /** The ids of the claims selected for a bulk action, across the sheet. */
  readonly selected = input.required<ReadonlySet<number>>();
  /** The sheet's people, by id and name: a claim can be moved to any of them but its own. */
  readonly people = input.required<ClaimTarget[]>();
  readonly saved = output<Claim>();
  /** A claim moved to another person: it is listed first under them. */
  readonly reassigned = output<Claim>();
  /** A claim's checkbox ticked (on) or cleared. */
  readonly selectedChange = output<{ id: number; on: boolean }>();

  protected readonly amountInput = signal('');
  protected readonly dateInput = signal('');
  protected readonly noteInput = signal('');
  protected readonly correctsInput = signal('');
  protected readonly editingId = signal<number | null>(null);
  protected readonly error = signal<string | null>(null);
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;
  /** The error of each claim's last refused status change, by claim id. */
  protected readonly actionErrors = signal<ReadonlyMap<number, string>>(new Map());
  /** The reason typed for rejecting each claim, by claim id. */
  protected readonly reasons = signal<ReadonlyMap<number, string>>(new Map());
  /** The person id chosen to move each claim to, by claim id. */
  protected readonly targets = signal<ReadonlyMap<number, string>>(new Map());
  /** The people a claim of this person can be moved to. */
